function bsample(data,w,h,x,y){
  if(x<0)x=0; else if(x>w-1)x=w-1;
  if(y<0)y=0; else if(y>h-1)y=h-1;
  var x0=Math.floor(x), y0=Math.floor(y);
  var x1=x0+1, y1=y0+1;
  if(x1>w-1)x1=w-1; if(y1>h-1)y1=h-1;
  var fx=x-x0, fy=y-y0;
  var i00=(y0*w+x0)*4, i10=(y0*w+x1)*4, i01=(y1*w+x0)*4, i11=(y1*w+x1)*4;
  var o0=data[i00]+(data[i10]-data[i00])*fx;
  var o1=data[i01]+(data[i11]-data[i01])*fx;
  var r=o0+(o1-o0)*fy;
  var g0=data[i00+1]+(data[i10+1]-data[i00+1])*fx;
  var g1=data[i01+1]+(data[i11+1]-data[i01+1])*fx;
  var g=g0+(g1-g0)*fy;
  var b0=data[i00+2]+(data[i10+2]-data[i00+2])*fx;
  var b1=data[i01+2]+(data[i11+2]-data[i01+2])*fx;
  var b=b0+(b1-b0)*fy;
  var a0=data[i00+3]+(data[i10+3]-data[i00+3])*fx;
  var a1=data[i01+3]+(data[i11+3]-data[i01+3])*fx;
  var a=a0+(a1-a0)*fy;
  return [r,g,b,a];
}

function rippleProcess(data,w,h,opts){
  opts=opts||{};
  var amp=opts.amplitude!=null?opts.amplitude:8;
  var wl=opts.wavelength!=null?opts.wavelength:24;
  var ang=opts.angle!=null?opts.angle:0;
  if(wl<1)wl=1;
  var cx=(opts.centerX!=null?opts.centerX:0.5)*w;
  var cy=(opts.centerY!=null?opts.centerY:0.5)*h;
  var dx=Math.cos(ang*Math.PI/180), dy=Math.sin(ang*Math.PI/180);
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var i=(y*w+x)*4;
    out[i+3]=data[i+3];
    if(amp===0){ out[i]=data[i];out[i+1]=data[i+1];out[i+2]=data[i+2]; continue; }
    var rx=x-cx, ry=y-cy;
    var dist=rx*dx+ry*dy;
    var off=amp*Math.sin(dist/wl*2*Math.PI);
    var p=bsample(data,w,h,x+dx*off, y+dy*off);
    out[i]=p[0];out[i+1]=p[1];out[i+2]=p[2];
  }
  return out;
}

var EXPORTS={rippleProcess:rippleProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RippleForgePure = EXPORTS; }
